   142→    public TransformedInputRow(final InputRow row, final Map<String, RowFunction> transforms)
   143→    {
   144→      this.row = row;
   145→      this.transforms = transforms;
   146→    }
   147→
   148→    @Override
   149→    public List<String> getDimensions()
   150→    {
   151→      return row.getDimensions();
   152→    }
   153→
   154→    @Override
   155→    public long getTimestampFromEpoch()
   156→    {
   157→      final RowFunction transform = transforms.get(ColumnHolder.TIME_COLUMN_NAME);
   158→      if (transform != null) {
   159→        //noinspection ConstantConditions time column is never null
   160→        return Rows.objectToNumber(ColumnHolder.TIME_COLUMN_NAME, transform.eval(row), true).longValue();
   161→      } else {
   162→        return row.getTimestampFromEpoch();
   163→      }
   164→    }
   165→
   166→    @Override
   167→    public DateTime getTimestamp()
   168→    {
   169→      final RowFunction transform = transforms.get(ColumnHolder.TIME_COLUMN_NAME);
   170→      if (transform != null) {
   171→        return DateTimes.utc(getTimestampFromEpoch());
   172→      } else {
   173→        return row.getTimestamp();
   174→      }
   175→    }
   176→
   177→    @Override
   178→    public List<String> getDimension(final String dimension)
   179→    {
   180→      final RowFunction transform = transforms.get(dimension);
   181→      if (transform != null) {
   182→        return Rows.objectToStrings(transform.eval(row));
   183→      } else {
   184→        return row.getDimension(dimension);
   185→      }
   186→    }
   187→
   188→    @Override
   189→    public Object getRaw(final String column)
   190→    {
   191→      final RowFunction transform = transforms.get(column);
   192→      if (transform != null) {
   193→        return transform.eval(row);
   194→      } else {
   195→        return row.getRaw(column);
   196→      }
   197→    }
   198→
   199→    @Override
   200→    public Number getMetric(final String metric)
   201→    {
   202→      final RowFunction transform = transforms.get(metric);
   203→      if (transform != null) {
   204→        return Rows.objectToNumber(metric, transform.eval(row), true);
   205→      } else {
   206→        return row.getMetric(metric);
   207→      }
   208→    }
   209→
   210→    @Override
